lessons.solution:
import json


def strip_fence(text):
    text = text.strip()
    if text.startswith("```"):
        lines = text.splitlines()
        text = "\n".join(lines[1:-1])
    return text


def parse_reply(text):
    data = json.loads(strip_fence(text))
    if not isinstance(data, dict):
        raise ValueError("reply is not an object")
    problems = []
    title = data.get("title")
    if not isinstance(title, str) or not title:
        problems.append("title")
    priority = data.get("priority")
    if (
        type(priority) is not int
        or not 1 <= priority <= 5
    ):
        problems.append("priority")
    tags = data.get("tags", [])
    if not isinstance(tags, list) or not all(
        isinstance(tag, str) for tag in tags
    ):
        problems.append("tags")
    if problems:
        raise ValueError("invalid: " + ", ".join(problems))
    return {
        "title": title,
        "priority": priority,
        "tags": tags,
    }

checks.code:
for text in ["not json", "[1, 2]", '"text"', ""]:
    raised = False
    try:
        parse_reply(text)
    except ValueError:
        raised = True
    assert raised, f"{text!r} should raise ValueError"

message = None
try:
    parse_reply('{"title": 1, "priority": 9, "tags": 2}')
except ValueError as error:
    message = str(error)
assert message is not None, "should raise ValueError"
for field in ("title", "priority", "tags"):
    assert field in message, message

