def add(a, b):
    return a + b


def word_count(text):
    return len(text.split())


TOOLS = {"add": add, "word_count": word_count}


def failed(message):
    return {"ok": False, "error": message}


def run_tool_call(call, tools=TOOLS):
    if not isinstance(call, dict):
        return failed("call is not an object")
    name = call.get("name")
    if not isinstance(name, str) or name not in tools:
        return failed(f"unknown tool: {name}")
    arguments = call.get("arguments", {})
    if not isinstance(arguments, dict):
        return failed("arguments must be an object")
    try:
        result = tools[name](**arguments)
    except Exception as error:
        kind = type(error).__name__
        return failed(f"{kind}: {error}")
    return {"ok": True, "result": result}

checks.code:
for name in ["nope", "eval", "__import__", None, ["add"]]:
    got = run_tool_call({"name": name, "arguments": {}})
    assert got["ok"] is False and "error" in got, (name, got)

for call in [{}, "add", None, {"name": "add", "arguments": [1, 2]}]:
    got = run_tool_call(call)
    assert got["ok"] is False and "error" in got, (call, got)

