lessons.solution:
from decimal import Decimal, InvalidOperation


def normalize_emails(emails):
    seen = set()
    result = []
    for email in emails:
        email = email.strip().lower()
        if email and email not in seen:
            seen.add(email)
            result.append(email)
    return result


def page_of(items, page, size):
    if page < 1:
        raise ValueError("page starts at 1")
    start = (page - 1) * size
    return items[start:start + size]


def total_cents(prices):
    total = Decimal(0)
    for price in prices:
        try:
            total += Decimal(price)
        except InvalidOperation:
            raise ValueError(f"bad price: {price!r}")
    return int(total * 100)

checks.code:
for page in [0, -1]:
    raised = False
    try:
        page_of([1, 2], page, 1)
    except ValueError:
        raised = True
    assert raised, f"page {page} should raise ValueError"

for bad in ["abc", ""]:
    raised = False
    try:
        total_cents(["1.00", bad])
    except ValueError:
        raised = True
    assert raised, f"{bad!r} should raise ValueError"
